// Make base data accessible globally
window.REVA_35_LABORATORIES = REVA_35_LABORATORIES;

/**
 * Metrology Official Symbol Generator for all 35 Accredited Laboratories
 * 100% faithful to the official Reva Calibration & NABL accredited scope reference chart.
 */
function getLabSvgIcon(labId, size = 58) {
  const id = Number(labId);
  if (id >= 1 && id <= 35) {
    return `<img src="assets/images/labs/lab_${id}.png?v=hd_crisp" alt="Lab ${id} Metrology Symbol" class="lab-metrology-icon" width="${size}" height="${size}" loading="lazy">`;
  }
  return `<svg width="${size}" height="${size}" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="12" y="12" width="24" height="24" rx="4"/><circle cx="24" cy="24" r="6"/></svg>`;
}
window.getLabSvgIcon = getLabSvgIcon;

// Active view mode: 'matrix' (Symbol Matrix matching reference chart) or 'cards' (Detailed Cards)
window.currentLabViewMode = window.currentLabViewMode || 'matrix';

// Provide helper method for rendering laboratories
function renderLaboratories(filteredLabs) {
  const container = document.getElementById('labs-grid-target');
  if (!container) return;

  const labsToRender = filteredLabs || (typeof SiteData !== 'undefined' ? SiteData.getLabs() : REVA_35_LABORATORIES);

  if (labsToRender.length === 0) {
    container.className = 'labs-grid';
    container.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 3rem; background: var(--bg-surface); border: 1px dashed var(--orange-border); border-radius: var(--radius-md);">
        <p style="color: var(--orange-primary); font-family: var(--font-technical); text-transform: uppercase;">No laboratories match your current filter query.</p>
        <button class="btn btn-ghost" onclick="resetLabFilter()" style="margin-top: 1rem;">View All Laboratories</button>
      </div>
    `;
    return;
  }

  // 1. Symbol Matrix View (Grid of all 35 Lab Symbols & Names - Faithful to Official Reference Chart)
  if (window.currentLabViewMode === 'matrix') {
    container.className = 'lab-symbol-matrix';
    container.innerHTML = labsToRender.map(lab => {
      const insts = getLabInstruments(lab);
      return `
      <div class="lab-symbol-tile corner-accents" data-category="${lab.category}" onclick="openLabDetails(${lab.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openLabDetails(${lab.id});}" role="button" tabindex="0" aria-label="View specifications for ${lab.name}" title="Click to open ${lab.name} and inspect all ${insts.length} accredited instruments">
        <div class="lab-symbol-box">
          ${getLabSvgIcon(lab.id, 58)}
        </div>
        <h3 class="lab-symbol-name">${lab.name}</h3>
      </div>
    `;
    }).join('');
  }
  // 2. Detailed Technical Cards View (with symbol in card and instrument chips)
  else {
    container.className = 'labs-grid';
    container.innerHTML = labsToRender.map(lab => {
      const insts = getLabInstruments(lab);

      // Extract distinct, cleanly-formatted instrument names (no duplicates, no bracket noise)
      const seenPills = new Set();
      const distinctPillNames = [];
      for (const inst of insts) {
        const raw = inst.name || '';
        const base = raw
          .replace(/\[.*?\]/g, '')
          .split('(')[0]
          .split(' - ')[0]
          .split(',')[0]
          .trim();
        if (base && !seenPills.has(base.toLowerCase())) {
          seenPills.add(base.toLowerCase());
          distinctPillNames.push(base);
          if (distinctPillNames.length >= 3) break;
        }
      }

      const previewPills = distinctPillNames.map(name => `<span class="lab-preview-pill" title="${name}">${name}</span>`).join('');
      const remainingCount = insts.length - distinctPillNames.length;
      const moreCount = remainingCount > 0 
        ? `<span class="lab-preview-pill lab-preview-more">+${remainingCount} more</span>` 
        : '';

      const safeScope = (lab.scope || '').replace(/"/g, '&quot;');

      return `
      <div class="lab-item-card corner-accents" data-category="${lab.category}" onclick="openLabDetails(${lab.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openLabDetails(${lab.id});}" role="button" tabindex="0" aria-label="View specifications for ${lab.name}">
        <div class="lab-card-top">
          <span class="lab-index-tag">${String(lab.id).padStart(2, '0')} // ${lab.code || 'LAB-' + lab.id}</span>
          <div class="badge-pill" style="font-size: 0.65rem; padding: 2px 8px;">
            ${lab.onSite ? 'On-Site / Lab' : 'Lab Primary'}
          </div>
        </div>
        <div class="lab-card-symbol-frame">
          ${getLabSvgIcon(lab.id, 42)}
        </div>
        <h3 class="lab-name-heading">${lab.name}</h3>
        <p class="lab-scope-details" title="${safeScope}">${lab.scope}</p>
        <div class="lab-card-instruments-preview">
          ${previewPills}
          ${moreCount}
        </div>
        <div class="lab-card-action-bar">
          <span>Open ${insts.length} Accredited Instruments</span>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="9 18 15 12 9 6"></polyline></svg>
        </div>
      </div>
    `;
    }).join('');
  }
}


