function getLabInstruments(lab) {
  if (!lab) return [];
  const labId = Number(lab.id);

  // Check persistent SiteData instruments first
  if (typeof SiteData !== 'undefined' && typeof SiteData.getInstrumentsByLabId === 'function') {
    const fromSiteData = SiteData.getInstrumentsByLabId(labId);
    if (Array.isArray(fromSiteData) && fromSiteData.length > 0) {
      return fromSiteData;
    }
  }

  if (Array.isArray(lab.instruments) && lab.instruments.length > 0) {
    return lab.instruments;
  }
  if (REVA_LAB_INSTRUMENTS[labId] && REVA_LAB_INSTRUMENTS[labId].length > 0) {
    return REVA_LAB_INSTRUMENTS[labId];
  }
  // Fallback: parse comma-separated scope
  if (typeof lab.scope === 'string') {
    return lab.scope.split(/[,;&]/).map((item, idx) => {
      const trimmed = item.trim();
      return {
        name: trimmed,
        range: "Full accredited industrial scope",
        parameters: "Scale accuracy, linearity, repeatability, calibration verification",
        equipment: lab.equipment || "Certified Master Standards",
        cmc: lab.cmc || "ISO 17025 accredited uncertainty",
        standards: lab.standards || "ISO/IEC 17025: 2017",
        type: "tool"
      };
    }).filter(i => i.name.length > 1);
  }
  return [];
}

function getInstrumentSvgIcon(type) {
  const t = (type || 'tool').toLowerCase();
  if (t.includes('caliper')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M4 4v6M8 7v-3M12 7v-2M16 7v-3M20 4v6"/><path d="M9 11v9l3-2v-4h4v4l3-2v-7z"/></svg>`;
  }
  if (t.includes('micrometer')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12a7 7 0 0 0 14 0H5z"/><rect x="11" y="8" width="6" height="4" rx="1"/><path d="M17 9h4v2h-4zM2 12h3"/></svg>`;
  }
  if (t.includes('gauge') || t.includes('dial')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 12l3-3"/><circle cx="12" cy="12" r="1.5"/><path d="M12 3v3M12 18v3M3 12h3M18 12h3"/></svg>`;
  }
  if (t.includes('laser') || t.includes('interferometer') || t.includes('ballbar')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg>`;
  }
  if (t.includes('weight') || t.includes('scale') || t.includes('balance')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18M6 8l6-3 6 3M6 8l-3 7h6l-3-7zM18 8l-3 7h6l-3-7z"/></svg>`;
  }
  if (t.includes('pipette') || t.includes('burette') || t.includes('flask') || t.includes('pycnometer') || t.includes('cylinder') || t.includes('beaker')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 2v7.31M14 2v7.31M8.5 2h7M14 9.3l4.5 9.7a2 2 0 0 1-1.8 2.8H7.3a2 2 0 0 1-1.8-2.8L10 9.3z"/><path d="M8 17h8"/></svg>`;
  }
  if (t.includes('viscometer') || t.includes('hydrometer') || t.includes('density')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20M8 6h8M9 12h6M7 18h10"/><circle cx="12" cy="18" r="3"/></svg>`;
  }
  if (t.includes('pressure') || t.includes('dwt') || t.includes('bourdon') || t.includes('vacuum')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 12l2.5-4"/><path d="M7 16a6 6 0 0 1 10 0"/></svg>`;
  }
  if (t.includes('torque') || t.includes('wrench')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></svg>`;
  }
  if (t.includes('dmm') || t.includes('electrical') || t.includes('calibrator') || t.includes('megger')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="2" width="16" height="20" rx="2"/><rect x="7" y="5" width="10" height="5" rx="1"/><circle cx="12" cy="15" r="3"/><path d="M12 15l1.5-1.5"/></svg>`;
  }
  if (t.includes('thermal') || t.includes('prt') || t.includes('thermocouple') || t.includes('blackbody')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 14.76V3.5a2.5 2.5 0 0 0-5 0v11.26a4.5 4.5 0 1 0 5 0z"/><circle cx="11.5" cy="17.5" r="2"/></svg>`;
  }
  if (t.includes('flow') || t.includes('anemo') || t.includes('coriolis')) {
    return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h20M17 7l5 5-5 5M6 17l-4-5 4-5"/></svg>`;
  }
  return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg>`;
}

// Global state for lab inspection modal
window.activeLabDetailId = 1;
window.allInstrumentsExpanded = false;

// Laboratory Detail Modal Functions
function openLabDetails(labId) {
  const labs = (typeof SiteData !== 'undefined' && typeof SiteData.getLabs === 'function') 
    ? SiteData.getLabs() 
    : REVA_35_LABORATORIES;
  const lab = labs.find(l => String(l.id) === String(labId));
  if (!lab) return;

  window.activeLabDetailId = Number(lab.id);
  window.allInstrumentsExpanded = false;

  const modal = document.getElementById('lab-detail-modal');
  if (!modal) return;

  const codeEl = document.getElementById('lab-modal-code');
  const catEl = document.getElementById('lab-modal-cat');
  const siteEl = document.getElementById('lab-modal-site');
  const titleEl = document.getElementById('lab-modal-title');
  const taglineEl = document.getElementById('lab-modal-tagline');
  if (codeEl) codeEl.textContent = `${String(lab.id).padStart(2, '0')} // ${lab.code || 'LAB-' + lab.id}`;
  if (catEl) catEl.textContent = (lab.category || 'METROLOGY').toUpperCase();
  if (siteEl) siteEl.textContent = lab.onSite ? 'On-Site & Permanent Lab' : 'Permanent Lab Facility';
  if (titleEl) titleEl.textContent = lab.name;
  if (taglineEl) taglineEl.textContent = lab.tagline || 'NABL Accredited ISO/IEC 17025: 2017 • Unbroken Traceability to NPL & NIST';

  const navIndicator = document.getElementById('lab-nav-indicator');
  if (navIndicator) {
    navIndicator.textContent = `${String(lab.id).padStart(2, '0')} / 35`;
  }

  const symbolEl = document.getElementById('lab-modal-symbol-box');
  if (symbolEl) symbolEl.innerHTML = getLabSvgIcon(lab.id, 54);

  // Metrics Ribbon
  const instruments = getLabInstruments(lab);
  const instCountEl = document.getElementById('lab-modal-inst-count');
  const instSubEl = document.getElementById('lab-modal-inst-sub');
  const statCmcEl = document.getElementById('lab-modal-stat-cmc');
  const statCmcSubEl = document.getElementById('lab-modal-stat-cmc-sub');
  const statEnvEl = document.getElementById('lab-modal-stat-env');
  const statEnvSubEl = document.getElementById('lab-modal-stat-env-sub');

  const countDisplay = (instruments && instruments.length > 0)
    ? `${instruments.length} NABL Scopes`
    : (lab.instCount || 'Direct NABL Scope');
  if (instCountEl) instCountEl.textContent = countDisplay;
  if (instSubEl) instSubEl.textContent = lab.instSub || 'Direct NABL Scope';
  if (statCmcEl) statCmcEl.textContent = lab.statCmc || (lab.cmc ? lab.cmc.split('|')[0].replace('Expanded Uncertainty:', '').trim() : '± 1.2 µm');
  if (statCmcSubEl) statCmcSubEl.textContent = lab.cmcSub || 'Expanded (k=2, 95.45%)';
  if (statEnvEl) statEnvEl.textContent = lab.envControl || '20°C ± 1°C';
  if (statEnvSubEl) statEnvSubEl.textContent = lab.envControlSub || 'RH 45% ± 5% Class 100k';

  // Section 1: Interactive Instruments Showcase
  const instCountHeading = document.getElementById('lab-modal-instruments-count');
  if (instCountHeading) instCountHeading.textContent = instruments.length;

  const expandAllBtn = document.getElementById('btn-expand-all-instruments');
  const expandAllLabel = document.getElementById('expand-all-label');
  if (expandAllLabel) expandAllLabel.textContent = 'Expand All Instruments';

  const accordionContainer = document.getElementById('lab-instruments-accordion');
  if (accordionContainer) {
    if (instruments.length === 0) {
      accordionContainer.innerHTML = `<div style="padding: 2rem; text-align: center; color: var(--text-muted);">No specific instruments logged for this laboratory.</div>`;
    } else {
      accordionContainer.innerHTML = instruments.map((inst, idx) => `
        <div class="lab-instrument-item corner-accents" id="lab-inst-${idx}" style="--inst-delay: ${(idx * 0.045).toFixed(2)}s;">
          <div class="lab-instrument-summary" onclick="toggleInstrument(${idx})" role="button" tabindex="0" aria-expanded="false" aria-controls="lab-inst-drawer-${idx}">
            <div class="lab-inst-left">
              <span class="lab-inst-num">#${String(idx + 1).padStart(2, '0')}</span>
              <div class="lab-inst-icon-wrap">
                ${getInstrumentSvgIcon(inst.type)}
              </div>
              <div class="lab-inst-info">
                <h4 class="lab-inst-name">${inst.name}</h4>
                <div class="lab-inst-tags">
                  <span class="lab-inst-tag lab-inst-tag-range">Range: ${inst.range}</span>
                  <span class="lab-inst-tag lab-inst-tag-cmc">CMC: ${inst.cmc}</span>
                </div>
              </div>
            </div>
            <div class="lab-inst-right">
              <span class="lab-inst-status">NABL ISO 17025</span>
              <div class="lab-inst-chevron">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"></polyline></svg>
              </div>
            </div>
          </div>
          <div class="lab-instrument-drawer" id="lab-inst-drawer-${idx}">
            <div class="lab-instrument-drawer-inner">
              <div class="lab-inst-specs-grid">
                ${(() => {
                  const specItems = [];
                  const excludedSpecs = new Set(['nabl scope s.no', 'nabl scope s.no.', 'nabl s.no', 's.no', 's.no.', 'scope s.no', 'input', 'output']);
                  if (Array.isArray(inst.specs) && inst.specs.length > 0) {
                    inst.specs.forEach(s => {
                      if (s.name && s.value && !excludedSpecs.has(s.name.trim().toLowerCase())) {
                        specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">${s.name}</div><div class="lab-inst-spec-desc">${s.value}</div></div>`);
                      }
                    });
                  } else {
                    if (inst.parameters) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Parameters Measured</div><div class="lab-inst-spec-desc">${inst.parameters}</div></div>`);
                    if (inst.equipment) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Master Standards Used</div><div class="lab-inst-spec-desc">${inst.equipment}</div></div>`);
                    if (inst.standards) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Governing Standards</div><div class="lab-inst-spec-desc">${inst.standards}</div></div>`);
                  }
                  if (inst.accuracy && !specItems.some(i => i.includes(inst.accuracy))) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Accuracy / CMC</div><div class="lab-inst-spec-desc">${inst.accuracy}</div></div>`);
                  if (inst.resolution) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Resolution</div><div class="lab-inst-spec-desc">${inst.resolution}</div></div>`);
                  if (inst.display) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Display / Readout</div><div class="lab-inst-spec-desc">${inst.display}</div></div>`);
                  if (inst.applications) specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Applications</div><div class="lab-inst-spec-desc">${inst.applications}</div></div>`);
                  if (inst.features) { const cleanF = inst.features.replace(/\s*\(S\.No:\s*\d+\)\.?/gi, "").trim(); specItems.push(`<div class="lab-inst-spec-col"><div class="lab-inst-spec-title">Features</div><div class="lab-inst-spec-desc">${cleanF.endsWith(".") ? cleanF : cleanF + "."}</div></div>`); }
                  return specItems.join('');
                })()}
              </div>
              <div class="lab-inst-action-bar">
                <div class="lab-inst-guarantee">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
                  <span>ISO/IEC 17025 Accredited Calibration Certificate with Traceability to NPL/NIST</span>
                </div>
                <button type="button" class="btn btn-primary btn-sm lab-inst-quote-btn" onclick="requestInstrumentQuote('${inst.name.replace(/'/g, "\\\'")}', '${lab.name.replace(/'/g, "\\\'")}')">
                  <span>Enquire / Calibrate this Instrument</span>
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg>
                </button>
              </div>
            </div>
          </div>
        </div>
      `).join('');
    }
  }

  // Wire quote button to open quotation modal with pre-filled service name
  const quoteBtn = document.getElementById('lab-modal-quote-btn');
  if (quoteBtn) {
    quoteBtn.onclick = function() {
      closeLabDetails();
      if (typeof window.openQuoteModal === 'function') {
        window.openQuoteModal(`Calibration Service — ${lab.name} (${lab.code})`, lab);
      }
    };
  }

  modal.scrollTop = 0;
  modal.setAttribute('data-lenis-prevent', 'true');
  modal.setAttribute('data-lenis-prevent-wheel', 'true');
  modal.setAttribute('data-lenis-prevent-touch', 'true');
  modal.classList.add('active');
  document.body.classList.add('lab-modal-open');
  document.documentElement.classList.add('lab-modal-open');
  try { modal.focus(); } catch (e) {}
}

function toggleInstrument(index) {
  const item = document.getElementById(`lab-inst-${index}`);
  if (!item) return;
  const wasActive = item.classList.contains('active');
  item.classList.toggle('active');
  const summary = item.querySelector('.lab-instrument-summary');
  if (summary) {
    summary.setAttribute('aria-expanded', !wasActive);
  }
}

function toggleExpandAllInstruments() {
  const items = document.querySelectorAll('.lab-instrument-item');
  if (items.length === 0) return;

  window.allInstrumentsExpanded = !window.allInstrumentsExpanded;
  const shouldExpand = window.allInstrumentsExpanded;

  items.forEach(item => {
    if (shouldExpand) {
      item.classList.add('active');
      const summary = item.querySelector('.lab-instrument-summary');
      if (summary) summary.setAttribute('aria-expanded', 'true');
    } else {
      item.classList.remove('active');
      const summary = item.querySelector('.lab-instrument-summary');
      if (summary) summary.setAttribute('aria-expanded', 'false');
    }
  });

  const label = document.getElementById('expand-all-label');
  if (label) {
    label.textContent = shouldExpand ? 'Collapse All Instruments' : 'Expand All Instruments';
  }
  const icon = document.getElementById('expand-icon');
  if (icon) {
    icon.style.transform = shouldExpand ? 'rotate(180deg)' : 'rotate(0deg)';
    icon.style.transition = 'transform 0.3s ease';
  }
}

function navigateLab(direction) {
  const currentId = window.activeLabDetailId || 1;
  let nextId = currentId + direction;
  if (nextId < 1) nextId = 35;
  if (nextId > 35) nextId = 1;
  openLabDetails(nextId);
}

function requestInstrumentQuote(instrumentName, labName) {
  closeLabDetails();
  if (typeof window.openQuoteModal === 'function') {
    window.openQuoteModal(`Calibration: ${instrumentName} — ${labName}`);
  }
}

function closeLabDetails() {
  const modal = document.getElementById('lab-detail-modal');
  if (modal) {
    modal.classList.remove('active');
  }
  document.body.classList.remove('lab-modal-open');
  document.documentElement.classList.remove('lab-modal-open');
  document.body.style.overflow = '';
}

// Global modal bindings
document.addEventListener('DOMContentLoaded', () => {
  const closeBtn = document.getElementById('lab-modal-close');
  if (closeBtn) {
    closeBtn.addEventListener('click', closeLabDetails);
  }

  const modal = document.getElementById('lab-detail-modal');
  if (modal) {
    modal.setAttribute('data-lenis-prevent', 'true');
    modal.setAttribute('data-lenis-prevent-wheel', 'true');
    modal.setAttribute('data-lenis-prevent-touch', 'true');
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeLabDetails();
    });
  }

  window.addEventListener('keydown', (e) => {
    const modal = document.getElementById('lab-detail-modal');
    if (modal && modal.classList.contains('active')) {
      if (e.key === 'Escape') {
        closeLabDetails();
      } else if (e.key === 'ArrowLeft') {
        navigateLab(-1);
      } else if (e.key === 'ArrowRight') {
        navigateLab(1);
      } else if (e.key === 'ArrowDown') {
        modal.scrollBy({ top: 100, behavior: 'smooth' });
      } else if (e.key === 'ArrowUp') {
        modal.scrollBy({ top: -100, behavior: 'smooth' });
      } else if (e.key === 'PageDown' || (e.key === ' ' && !['INPUT', 'TEXTAREA', 'BUTTON'].includes(e.target.tagName))) {
        e.preventDefault();
        modal.scrollBy({ top: window.innerHeight * 0.75, behavior: 'smooth' });
      } else if (e.key === 'PageUp') {
        e.preventDefault();
        modal.scrollBy({ top: -window.innerHeight * 0.75, behavior: 'smooth' });
      } else if (e.key === 'Home') {
        modal.scrollTo({ top: 0, behavior: 'smooth' });
      } else if (e.key === 'End') {
        modal.scrollTo({ top: modal.scrollHeight, behavior: 'smooth' });
      }
    }
  });
});

// Expose globally
window.REVA_35_LABORATORIES = REVA_35_LABORATORIES;
window.REVA_LAB_INSTRUMENTS = REVA_LAB_INSTRUMENTS;
window.getLabInstruments = getLabInstruments;
window.getInstrumentSvgIcon = getInstrumentSvgIcon;
window.renderLaboratories = renderLaboratories;
window.openLabDetails = openLabDetails;
window.closeLabDetails = closeLabDetails;
window.toggleInstrument = toggleInstrument;
window.toggleExpandAllInstruments = toggleExpandAllInstruments;
window.navigateLab = navigateLab;
window.requestInstrumentQuote = requestInstrumentQuote;
